from pathlib import Path
p=Path('frontend/src/App.jsx')
s=p.read_text(encoding='utf-8')
start=s.index('function Requests(){')
end=s.index('function Technicians(){',start)
new='''function Requests(){const blank={customer_id:"",location:"",description:"",assigned_technician:""};const[rows,setRows]=useState([]),[customers,setCustomers]=useState([]),[techs,setTechs]=useState([]),[f,setF]=useState(blank),[error,setError]=useState(""),[busy,setBusy]=useState(false);const load=()=>api("/requests").then(setRows).catch(e=>setError(e.message));useEffect(()=>{load();api("/customers").then(setCustomers).catch(()=>{});api("/technicians").then(setTechs).catch(()=>{})},[]);const add=async e=>{e.preventDefault();setError("");setBusy(true);try{await api("/requests",{method:"POST",body:JSON.stringify({customer_id:Number(f.customer_id),location:f.location,description:f.description})});setF(blank);load()}catch(e){setError(e.message)}finally{setBusy(false)}};const update=async(id,data)=>{setError("");try{await api(`/requests/${id}`,{method:"PATCH",body:JSON.stringify(data)});load()}catch(e){setError(e.message)}};const statusLabel={pending:"Pending",assigned:"Assigned",on_the_way:"On the Way",completed:"Completed",closed:"Closed"};return <Page title="Service Requests" sub="Live roadside assistance requests"><div className="cols"><form className="card form" onSubmit={add}><h2><Plus size={18}/> New Service Request</h2><p className="muted">Create a roadside assistance request and assign it to a mechanic.</p><label>CUSTOMER<select required value={f.customer_id} onChange={e=>setF({...f,customer_id:e.target.value})}><option value="">Select customer</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name} · {c.phone} · {c.vehicle_no}</option>)}</select></label><label>BREAKDOWN / PROBLEM<textarea required value={f.description} onChange={e=>setF({...f,description:e.target.value})} placeholder="Flat tyre, battery issue, breakdown..."/></label><label>LOCATION<input required value={f.location} onChange={e=>setF({...f,location:e.target.value})} placeholder="Current vehicle location"/></label>{error&&<p className="error">{error}</p>}<button className="primary" type="submit" disabled={busy}>{busy?"Creating…":"Create Service Request"}</button></form><div className="card"><h2>Request History</h2>{rows.length===0?<div className="empty"><MapPin/><h3>No service requests</h3><p className="muted">New roadside assistance requests will appear here.</p></div>:rows.map(r=><div className="row" key={r.id}><div style={{minWidth:0}}><b>#{r.id} · {r.customer_name||"Customer not linked"}</b><small>{r.customer_phone||""} · {r.location||"Location not set"}</small><small>{r.description||"No problem description"}</small><small>{r.assigned_technician?`Mechanic: ${r.assigned_technician}`:"Mechanic not assigned"} · {new Date(r.created_at).toLocaleString("en-IN")}</small></div><div style={{display:"flex",gap:6,flexWrap:"wrap",justifyContent:"flex-end"}}><select value={r.assigned_technician||""} onChange={e=>update(r.id,{assigned_technician:e.target.value,status:e.target.value?"assigned":r.status})}><option value="">Assign Mechanic</option>{techs.filter(t=>t.active!==false).map(t=><option key={t.id} value={t.name}>{t.name} · {t.phone}</option>)}</select><select value={r.status||"pending"} onChange={e=>update(r.id,{status:e.target.value})}>{Object.entries(statusLabel).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></div></div>)}</div></div></Page>}\n'''
p.write_text(s[:start]+new+s[end:],encoding='utf-8')
print('Requests UI patched')
